WebdriverIO (8 and 9) helper for this template — in a WebdriverIO suite, use it as written:
Facts:
  • hidden copies: each plan card also exists for other products — scoped by div[data-plan-type="teams"]
  • no attribute carries the plan name on every card (data-plan-name is empty on "Team") — a card is found by its toggle input's aria-label, else by its exact visible title
  • "Team Pro" shares the "Team" card behind a toggle: hidden radio inputs operated by their labels — showPlan(title) switches it
  • each card holds a hidden Choose and price per toggle state — act on the displayed one
  • the "Volume" card has no Choose button (its price line is promo text)
  • the toggle inputs are hidden: assert the selected state or the label text, not that the input exists — an existence check passes with nothing on screen
```js
const planCards = () => $$('div[data-plan-type="teams"] div.simplification-card');

const isShown = async (el) => el.isDisplayed();
async function firstShown(els) {
  for (const el of els) if (await isShown(el)) return el;
  return undefined;
}

async function planTitles() {
  const titles = [];
  for (const card of await planCards()) {
    const toggles = await card.$$('input.card-toggle__input');
    if (toggles.length) for (const t of toggles) titles.push(await t.getAttribute('aria-label'));
    else titles.push((await card.$('h3.simplification-card__title').getText()).trim());
  }
  return titles;
}

async function planCard(title) {
  for (const card of await planCards()) {
    if (await card.$(`input.card-toggle__input[aria-label="${title}"]`).isExisting()) return card;
    const heading = await card.$('h3.simplification-card__title');
    if ((await heading.isExisting()) && (await heading.getText()).trim() === title) return card;
  }
  throw new Error(`No plan card titled "${title}" — plans on the page: ${(await planTitles()).join(', ')}`);
}

// Act, then wait for the state the act should produce: the toggle is selected.
async function showPlan(title) {
  const card = await planCard(title);
  const toggle = await card.$(`input.card-toggle__input[aria-label="${title}"]`);
  if ((await toggle.isExisting()) && !(await toggle.isSelected())) {
    await card.$(`label[for="${await toggle.getAttribute('id')}"]`).click();
    await browser.waitUntil(() => toggle.isSelected(), { timeoutMsg: `Plan "${title}" was not selected after clicking its toggle label` });
  }
  return card;
}

async function choose(title) {
  const button = await firstShown(await (await showPlan(title)).$$('input[type="submit"][value="Choose"]'));
  if (!button) throw new Error(`Plan "${title}": no displayed Choose button in its card`);
  return button;
}

async function price(title) {
  const amount = await firstShown(await (await showPlan(title)).$$('div.simplification-card__price'));
  if (!amount) throw new Error(`Plan "${title}": no displayed price in its card`);
  return amount;
}
```
