WebdriverIO (8 and 9) helper for this template — in a WebdriverIO suite, use it as written:
Facts:
  • column headers are in a separate table above the rows; plan names are h3.simplification-card__title, or a toggle input's aria-label ("Team" / "Team Pro" share a column)
  • hidden copies: every comparison table also exists for other products — scoped by div[data-plan-type="teams"]
  • the feature name is span.comparison-table__feature-name in the row's first cell
```js
const TEAMS_TABLES = 'div[data-plan-type="teams"] table.comparison-table__table';

async function columnIndex(column) {
  const headers = await $(`${TEAMS_TABLES} tr`).$$('th');
  const seen = [];
  for (let i = 0; i < headers.length; i++) {
    const toggle = await headers[i].$(`input.card-toggle__input[aria-label="${column}"]`);
    if (await toggle.isExisting()) return i;
    const title = await headers[i].$('h3.simplification-card__title');
    const name = (await title.isExisting()) ? (await title.getText()).trim() : '';
    if (name === column) return i;
    const labels = [];
    for (const t of await headers[i].$$('input.card-toggle__input')) labels.push(await t.getAttribute('aria-label'));
    seen.push(labels.length ? labels.join(' / ') : name || '(feature names)');
  }
  throw new Error(`No comparison column "${column}" — columns: ${seen.join(', ')}`);
}

async function comparisonCell(feature, column) {
  const index = await columnIndex(column);
  const features = [];
  for (const row of await $$(`${TEAMS_TABLES} tr`)) {
    const name = await row.$('span.comparison-table__feature-name');
    if (!(await name.isExisting())) continue;
    const text = (await name.getText()).trim();
    if (text === feature) return (await row.$$('th, td'))[index];
    features.push(text);
  }
  throw new Error(`No comparison row "${feature}" — rows include: ${features.slice(0, 8).join(', ')}`);
}
